import {packs as styles} from './catalog.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeImage=s=>{try{const u=new URL(s);return u.protocol==='https:'?esc(u.href):''}catch{return ''}};
let snapshot=null,offset=0,lastStage='',lastCatalog='';
function art(p){const image=safeImage(p.image);return `<div class="pack-art" style="--glow:${p.glow};--accent:${p.accent};--pack:${p.pack}"><span class="badge">${esc(p.category)}</span>${image?`<img class="provider-pack" src="${image}" alt="${esc(p.name)}">`:'<div class="object-icon">◈</div>'}</div>`}
function allPacks(){return styles.map(p=>({...p,...snapshot?.catalog?.find(m=>m.id===p.id)}))}
function paint(){if(!snapshot)return;const now=Date.now()+offset,list=allPacks(),p=list.find(x=>x.id===snapshot.nextPack)||list[2],e=snapshot.event,phase=e?(now<e.revealAt?'opening':now<e.endsAt?'reveal':'waiting'):'waiting';
$('#connection').textContent=snapshot.status==='active'?'● Automation connected':'● Collector Crypt catalogue';
$('#mode-notice').innerHTML=`<span>${snapshot.status==='active'?'AUTOMATIC OPENER':snapshot.status==='paused'?'AUTOMATION PAUSED':snapshot.status==='disabled'?'AUTOMATION DISABLED':'SETUP REQUIRED'}</span> ${esc(snapshot.status==='active'?'Real creator-fee funding. Pulls are awarded to balance-weighted holders.':snapshot.status==='paused'?'Opening paused for operator review. Previous deliveries remain available.':snapshot.status==='disabled'?'Automatic purchases are disabled by the operator.':('Configuration incomplete: '+(snapshot.missing||[]).join(', ')))}`;
$('#next-pack').textContent=snapshot.nextPack?p.name:'Highest affordable pack';const seconds=Math.min(60,Math.max(0,Math.ceil((snapshot.nextRoundAt-now)/1000)));$('#round-timer').textContent=seconds===0?'Evaluating…':String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');$('#funded').textContent='Unused balance rolls over';$('#progress').style.width=(100-seconds/60*100)+'%';$('#pool').textContent=(Number(snapshot.feeBudgetLamports||0)/1e9).toFixed(4)+' SOL collected';$('#stage-status').textContent=snapshot.message;
const catalogKey=JSON.stringify([snapshot.catalogAt,snapshot.nextPack,snapshot.catalogError]);if(catalogKey!==lastCatalog){lastCatalog=catalogKey;$('#pack-grid').innerHTML=list.map(x=>`<article class="pack-card ${x.id===snapshot.nextPack?'next':''}">${art(x)}<div class="pack-info"><span class="pack-category">COLLECTOR CRYPT</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="pack-foot"><span>${snapshot.catalog?.find(m=>m.id===x.id)?'$'+Number(x.price).toLocaleString()+' USDC':'Price unavailable'}</span><span class="queued">${snapshot.catalogError?'Feed unavailable':x.available?'Available':'Unavailable'}</span></div></div></article>`).join('')}
const key=(e?.id||'idle')+phase+Boolean(e?.pull)+snapshot.status+snapshot.message;if(key!==lastStage){lastStage=key;$('#event-label').textContent=e?'OPENING #'+String(e.sequence).padStart(4,'0'):'FUNDED BY CREATOR FEES';if(phase==='opening'){$('#stage-content').innerHTML=`<div class="stage-pack opening">${art(p)}<div class="eyebrow">ONE SHARED COMMUNITY OPENING</div><h2>${esc(p.name)}</h2><p>Waiting for Collector Crypt to deliver the pull…</p></div>`}else if(phase==='reveal'&&e.pull){$('#stage-content').innerHTML=`<div class="stage-result reveal">${safeImage(e.pull.image)?`<img class="pull-image" src="${safeImage(e.pull.image)}" alt="${esc(e.pull.name)}">`:'<div class="pull-emoji">◈</div>'}<div><div class="rarity">✦ DELIVERED TO A HOLDER ✦</div><h2>${esc(e.pull.name)}</h2><p>${esc(e.winner.slice(0,6))}…${esc(e.winner.slice(-6))}</p><a class="verify-link" href="https://solscan.io/tx/${encodeURIComponent(e.deliverySignature)}" target="_blank" rel="noopener noreferrer">Verify delivery ↗</a></div></div>`}else{$('#stage-content').innerHTML=`<div class="waiting"><img class="drop-art" src="/pumpdrop.png" alt="Mint capsule descending on a parachute" width="210" height="210"><div class="eyebrow">${snapshot.status==='active'?'THE NEXT PULL IS BUILDING':'PUMPCARDS STATUS'}</div><h2>${snapshot.status==='active'?'Creator fees in. Community pulls out.':snapshot.status==='paused'?'Automatic opening is paused.':snapshot.status==='disabled'?'Automatic opening is switched off.':'Finish connecting the opener.'}</h2><p>${esc(snapshot.status==='active'?'Every minute, the highest affordable pack opens. Unspent fees carry forward.':snapshot.status==='disabled'?'The operator has not enabled live purchases.':snapshot.message)}</p></div>`}}
$('#recent').innerHTML=snapshot.history.length?snapshot.history.map(x=>`<article class="recent-pull">${safeImage(x.pull.image)?`<img src="${safeImage(x.pull.image)}" alt="${esc(x.pull.name)}">`:'<span class="symbol">◈</span>'}<div><b>${esc(x.pull.name)}</b><small>${esc(x.winner.slice(0,5))}…${esc(x.winner.slice(-5))}</small><a class="verify-link" href="https://solscan.io/tx/${encodeURIComponent(x.deliverySignature)}" target="_blank" rel="noopener noreferrer">Verified delivery ↗</a></div></article>`).join(''):'<p class="muted">Verified holder deliveries will appear here after the first opening.</p>';
}
async function sync(){const start=Date.now();try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error();snapshot=await r.json();offset=snapshot.serverTime-(start+Date.now())/2;paint()}catch{$('#connection').textContent='○ Feed unavailable';$('#stage-status').textContent='Reconnecting to the shared opening feed.'}finally{setTimeout(sync,1000)}}sync();setInterval(()=>{if(snapshot&&Date.now()+offset-snapshot.serverTime<3000)paint()},250);
